
const RES=['wood','brick','sheep','wheat','ore'],COL=['#e63946','#3b82f6','#f59e0b','#a855f7','#22a06b'];
const COST={road:{wood:1,brick:1},settle:{wood:1,brick:1,sheep:1,wheat:1},city:{wheat:2,ore:3}};
const C={wood:['Odun','#58a85a','#1f5a2a'],brick:['Tuğla','#e0804f','#8f3a1f'],sheep:['Koyun','#bfe585','#6fa83a'],wheat:['Buğday','#f8df80','#d4a72c'],ore:['Maden','#b3bdc7','#5e6b78'],desert:['Çöl','#f2e3b6','#c9a96a']};
const SHEEP_CARD_IMAGE='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 240"><defs><linearGradient id="w" x2="0" y2="1"><stop stop-color="#fffdf5"/><stop offset="1" stop-color="#d8d3c6"/></linearGradient></defs><ellipse cx="145" cy="194" rx="88" ry="12" fill="#5c4631" opacity=".16"/><g fill="url(#w)" stroke="#b8b2a5" stroke-width="4"><circle cx="91" cy="111" r="38"/><circle cx="132" cy="91" r="43"/><circle cx="175" cy="99" r="42"/><circle cx="205" cy="133" r="35"/><circle cx="139" cy="139" r="45"/><circle cx="91" cy="151" r="30"/><circle cx="182" cy="151" r="34"/></g><path d="M198 111q28-25 48-4l15 23q-1 28-34 32l-28-14z" fill="#f0cdb4" stroke="#6a5143" stroke-width="5"/><path d="M232 113q-2-28 17-29 20 5 12 30" fill="#f0cdb4" stroke="#6a5143" stroke-width="5"/><circle cx="242" cy="132" r="5" fill="#302820"/><path d="M225 150q15 10 29-1" fill="none" stroke="#8b6253" stroke-width="4" stroke-linecap="round"/><path d="M85 167v31m49-23v26m54-30v27" stroke="#514136" stroke-width="11" stroke-linecap="round"/><path d="M76 198h20m28 3h20m36-4h20" stroke="#514136" stroke-width="7" stroke-linecap="round"/><path d="M67 100q-9-17 4-25 17-7 25 10" fill="#fffdf5" stroke="#b8b2a5" stroke-width="4"/></svg>');
const RIMG={wood:'data:image/png;base64,',brick:'data:image/png;base64,',sheep:SHEEP_CARD_IMAGE,wheat:'data:image/png;base64,',ore:'data:image/png;base64,'};
const ICON={
wood:'<path d="M0-.2L.12.02H.05L.15.16H-.15L-.05.02H-.12Z" fill="#14451c"/><rect x="-.025" y=".16" width=".05" height=".07" fill="#4e342e"/>',
brick:'<g fill="#7a2f16" stroke="#e9a37f" stroke-width=".012"><rect x="-.17" y="-.1" width=".16" height=".08"/><rect x="0" y="-.1" width=".16" height=".08"/><rect x="-.09" y="-.02" width=".16" height=".08"/><rect x="-.17" y=".06" width=".16" height=".08"/><rect x="0" y=".06" width=".16" height=".08"/></g>',
sheep:'<ellipse rx=".14" ry=".1" fill="#fff"/><circle cx=".13" cy="-.02" r=".05" fill="#333"/>',
wheat:'<path d="M0 .16V-.14M-.07 .16V-.08M.07 .16V-.08" stroke="#9a6b00" stroke-width=".02"/><g fill="#b8860b"><ellipse cy="-.15" rx=".03" ry=".06"/><ellipse cx="-.07" cy="-.1" rx=".03" ry=".05"/><ellipse cx=".07" cy="-.1" rx=".03" ry=".05"/></g>',
ore:'<path d="M-.2.14L-.05-.14L.03 0L.1-.08L.2.14Z" fill="#46515c"/><path d="M-.05-.14L-.1-.04L-.02-.06L.03 0Z" fill="#fff"/>',
desert:'<path d="M-.2.1Q-.1-.05 0 .1T.2.1" stroke="#b08a45" stroke-width=".03" fill="none"/>'};
const DEFS='<defs>'+Object.entries(C).map(([k,c])=>`<radialGradient id="g${k}"><stop offset="0" stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></radialGradient><g id="i${k}">${ICON[k]}</g>`).join('')+
'<linearGradient id=oc x1=0 y1=0 x2=1 y2=1><stop offset=0 stop-color="#27899a"/><stop offset=1 stop-color="#07394a"/></linearGradient><pattern id=wv width=".8" height=".5" patternUnits=userSpaceOnUse><path d="M0 .25Q.2 .1 .4 .25T.8 .25" stroke="#fff" stroke-opacity=".1" stroke-width=".03" fill=none /></pattern><filter id=sh x=-.5 y=-.5 width=2 height=2><feDropShadow dx=0 dy=.04 stdDeviation=.04 flood-opacity=".6"/></filter><filter id=glow x=-1 y=-1 width=3 height=3 color-interpolation-filters="sRGB"><feGaussianBlur stdDeviation=".075" result="blur"/><feFlood flood-color="#ffd76a" flood-opacity=".95" result="gold"/><feComposite in="gold" in2="blur" operator="in" result="halo"/><feMerge><feMergeNode in="halo"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>';
const $=id=>document.getElementById(id),rep=(n,x)=>Array(n).fill(x);
let g,host=false,peer,conn,conns=[],s=null,mode='r',lastDice='';
const opts=RES.map(k=>`<option value=${k}>${C[k][0]}</option>`).join('');$('g1').innerHTML=opts;$('g2').innerHTML=opts;$('g2').selectedIndex=3;$('g1').addEventListener('change',()=>{if(s)render()});
if(location.search.includes('oda='))$('cd').value=new URLSearchParams(location.search).get('oda');
function toast(m){const t=$('toast');t.textContent=m;t.style.display='block';clearTimeout(t.h);t.h=setTimeout(()=>t.style.display='none',2200)}

/* ---------- OYUN MOTORU (host tarayıcısında çalışır) ---------- */
const sh=a=>{for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]]}return a};
function reset(){
  const five=g&&g.players.length===5;
  const T=sh(five
    ? [...rep(6,'wood'),...rep(6,'sheep'),...rep(6,'wheat'),...rep(5,'brick'),...rep(5,'ore'),...rep(2,'desert')]
    : [...rep(4,'wood'),...rep(4,'sheep'),...rep(4,'wheat'),...rep(3,'brick'),...rep(3,'ore'),'desert']);
  const N=sh(five
    ? [2,3,3,4,4,4,5,5,5,5,6,6,6,6,8,8,8,8,9,9,9,10,10,10,11,11,12,12]
    : [2,3,3,4,4,5,5,6,6,8,8,9,9,10,10,11,11,12]);
  const old=g?g.players:[];
  g={phase:'lobby',players:old.map(p=>({...p,res:Object.fromEntries(RES.map(r=>[r,0]))})),hexes:[],V:{},E:{},adj:{},turn:0,rolled:false,rob:0,mustRob:false,d:[0,0],si:0,st:'s',order:[],last:null,log:[],win:null,longest:null};
  let k=0;
  const coords5=[[1,2,3],[0,1,2,3],[-2,-1,0,1,2],[-3,-2,-1,0,1,2],[-2,-1,0,1,2],[-2,-1,0,1],[-2,-1,0]];
  if(five){for(let ri=0;ri<7;ri++){const r=ri-3;for(const q of coords5[ri]) addHex(q,r);}}
  else {for(let q=-2;q<=2;q++)for(let r=-2;r<=2;r++)if(Math.abs(q+r)<=2)addHex(q,r);}
  function addHex(q,r){
    const res=T[k++],x=Math.sqrt(3)*(q+r/2),y=1.5*r,h={x,y,res,num:res=='desert'?0:N.pop(),v:[]};
    for(let i=0;i<6;i++){const a=Math.PI/3*i-Math.PI/6,cx=x+Math.cos(a),cy=y+Math.sin(a),id=Math.round(cx*100)+','+Math.round(cy*100);
      g.V[id]=g.V[id]||{id,x:cx,y:cy,o:null,c:false};g.adj[id]=g.adj[id]||[];h.v.push(id)}
    for(let i=0;i<6;i++){const a=h.v[i],b=h.v[(i+1)%6],id=[a,b].sort().join('|');
      if(!g.E[id]){g.E[id]={id,a,b,o:null};g.adj[a].push({e:id,o:b});g.adj[b].push({e:id,o:a})}}
    if(res=='desert')g.rob=g.hexes.length;g.hexes.push(h);
  }
  // Kıyıdaki tek komşulu kenarlardan dokuz liman seç; her yeni oyunda
  // tahta geometrisine göre eşit aralıklarla yerleşir.
  const edgeUse={};
  g.hexes.forEach(h=>h.v.forEach((a,i)=>{
    const b=h.v[(i+1)%6],id=[a,b].sort().join('|');
    edgeUse[id]=(edgeUse[id]||0)+1;
  }));
  const coast=Object.values(g.E).filter(e=>edgeUse[e.id]===1).sort((a,b)=>{
    const aa=Math.atan2((g.V[a.a].y+g.V[a.b].y)/2,(g.V[a.a].x+g.V[a.b].x)/2);
    const ab=Math.atan2((g.V[b.a].y+g.V[b.b].y)/2,(g.V[b.a].x+g.V[b.b].x)/2);
    return aa-ab;
  });
  const portTypes=['any','wood','any','brick','any','sheep','any','wheat','ore'];
  g.ports=portTypes.map((type,i)=>{
    const e=coast[Math.floor(i*coast.length/portTypes.length)];
    const a=g.V[e.a],b=g.V[e.b],x=(a.x+b.x)/2,y=(a.y+b.y)/2,len=Math.hypot(x,y)||1;
    return {id:e.id,a:e.a,b:e.b,type,x:x+x/len*.27,y:y+y/len*.27};
  });
}
function roadLength(player){
  const owned=Object.values(g.E).filter(e=>e.o===player);let best=0;
  function walk(vertex,used,first=false){
    let n=0;
    for(const edge of owned){if(used.has(edge.id))continue;
      let next=edge.a===vertex?edge.b:edge.b===vertex?edge.a:null;if(!next)continue;
      const blocked=!first&&g.V[vertex].o!==null&&g.V[vertex].o!==player;
      if(blocked)continue;
      const nextUsed=new Set(used);nextUsed.add(edge.id);
      n=Math.max(n,1+walk(next,nextUsed,false));
    }
    return n;
  }
  for(const edge of owned){best=Math.max(best,walk(edge.a,new Set([edge.id]),true),walk(edge.b,new Set([edge.id]),true))}
  return best;
}
function updateLongest(){
  const lengths=g.players.map((_,i)=>roadLength(i)),max=Math.max(0,...lengths),holders=lengths.map((v,i)=>v===max?i:-1).filter(i=>i>=0);
  if(max<5)g.longest=null;
  else if(holders.length===1)g.longest=holders[0];
  else if(g.longest===null||!holders.includes(g.longest))g.longest=null;
}
const vp=i=>Object.values(g.V).reduce((n,v)=>n+(v.o===i?(v.c?2:1):0),0)+(g.longest===i?2:0);
const can=(p,c)=>Object.keys(c).every(k=>p.res[k]>=c[k]),pay=(p,c)=>Object.keys(c).forEach(k=>p.res[k]-=c[k]);
const free=id=>g.V[id].o===null&&g.adj[id].every(n=>g.V[n.o].o===null);
const linked=(id,i)=>g.adj[id].some(n=>g.E[n.e].o===i)&&(g.V[id].o===null||g.V[id].o===i);
const roadOk=(e,i)=>g.V[e.a].o===i||g.V[e.b].o===i||linked(e.a,i)||linked(e.b,i);
function portRatio(player,give){
  let ratio=4;
  for(const port of (g.ports||[])){
    const owns=g.V[port.a].o===player||g.V[port.b].o===player;
    if(!owns)continue;
    if(port.type===give)ratio=Math.min(ratio,2);
    else if(port.type==='any')ratio=Math.min(ratio,3);
  }
  return ratio;
}
const L=t=>{g.log.unshift(t);g.log.length=Math.min(g.log.length,9)};
function act(b){
  const me=b.pid,p=g.players[me],t=b.t;
  if(t=='join'){
    if(g.phase!='lobby')return{err:'Oyun başladı'};if(g.players.length>=4)return{err:'Oda dolu (en fazla 4 oyuncu)'};
    const name=String(b.name||'Oyuncu').replace(/[<>&"']/g,'').slice(0,14)||'Oyuncu';
    g.players.push({name,col:COL[g.players.length],hasDice:!!b.hasDice,res:Object.fromEntries(RES.map(r=>[r,0]))});L(name+' katıldı');return{pid:g.players.length-1}}
  if(t=='reset'){if(g.phase=='over')reset();return{}}
  if(!p)return{err:'Oyuncu değilsin'};
  if(t=='start'){if(g.phase!='lobby'||g.players.length<2)return{err:'En az 2 oyuncu lazım'};
    const o=[...g.players.keys()];g.order=o.concat([...o].reverse());g.phase='setup';g.turn=g.order[0];L('Başlangıç: sırayla köy + yol');return{}}
  if(g.phase=='over'||g.phase=='lobby')return{err:'Şu an olmaz'};
  if(g.turn!==me)return{err:'Sıra sende değil'};
  if(g.phase=='setup'){
    if(g.st=='s'&&t!=='settle')return{err:'Önce parlayan köşe noktalarından birine başlangıç köyünü kur.'};
    if(g.st=='r'&&t!=='road')return{err:'Köyün kuruldu. Şimdi köyüne bağlı parlayan kenarlardan birine yol koy.'};
    if(t=='settle'){if(g.st!='s')return{err:'Şimdi yol koy'};if(!g.V[b.id]||!free(b.id))return{err:'Buraya olmaz'};
      g.V[b.id].o=me;g.last=b.id;g.st='r';
      if(g.si>=g.players.length)g.hexes.forEach(h=>{if(h.res!='desert'&&h.v.includes(b.id))p.res[h.res]++});return{}}
    if(t=='road'){const e=g.E[b.id];if(g.st!='r')return{err:'Önce köy koy'};
      if(!e||e.o!==null||(e.a!=g.last&&e.b!=g.last))return{err:'Son köyüne bitişik yol seç'};
      e.o=me;updateLongest();g.st='s';g.si++;
      if(g.si>=g.order.length){g.phase='play';g.turn=0;g.rolled=false;L('Kurulum bitti, zar atın!')}else g.turn=g.order[g.si];return{}}
    return{err:'Kurulumda sadece köy ve yol'}}
  if(g.mustRob){
    if(t!='robber')return{err:'Önce haydutu taşı'};if(!g.hexes[b.h]||b.h==g.rob)return{err:'Başka arazi seç'};
    g.rob=b.h;
    const vic=[...new Set(g.hexes[b.h].v.map(id=>g.V[id].o).filter(o=>o!==null&&o!==me))].filter(o=>RES.some(r=>g.players[o].res[r]>0));
    if(vic.length){const v=g.players[vic[Math.random()*vic.length|0]],bag=RES.flatMap(r=>rep(v.res[r],r)),r=bag[Math.random()*bag.length|0];
      v.res[r]--;p.res[r]++;L(`${p.name} haydutla ${v.name}'den kart çaldı`)}else L(p.name+' haydutu taşıdı');
    g.mustRob=false;return{}}
  if(t=='roll'||t=='manualRoll'){
    if(g.rolled)return{err:'Zaten zar attın'};
    if(t==='roll'&&p.hasDice)return{err:'Fiziksel zar seçtin. Sonucu kendin gir.'};
    if(t==='manualRoll'&&!p.hasDice)return{err:'Fiziksel zar seçeneğin açık değil.'};
    const a=t==='roll'?1+(Math.random()*6|0):Number(b.a);
    const c=t==='roll'?1+(Math.random()*6|0):Number(b.b);
    if(!Number.isInteger(a)||!Number.isInteger(c)||a<1||a>6||c<1||c>6)return{err:'Her iki zar da 1 ile 6 arasında olmalı.'};
    const d=a+c;g.d=[a,c];g.rolled=true;L(`${p.name} ${t==='roll'?'bilgisayar zarıyla':'fiziksel zarla'} ${a}+${c}=${d} attı`);
    if(d==7){
      g.players.forEach(pl=>{const total=RES.reduce((n,r)=>n+pl.res[r],0);if(total>7){let drop=Math.floor(total/2);while(drop-->0){const bag=RES.flatMap(r=>rep(pl.res[r],r));if(!bag.length)break;const r=bag[Math.random()*bag.length|0];pl.res[r]--;}}});
      L('7 geldi! 7’den fazla kartı olan oyuncular kartlarının yarısını kaybetti.');g.mustRob=true;return{}}
    g.hexes.forEach((h,i)=>{if(h.num==d&&i!=g.rob)h.v.forEach(id=>{const v=g.V[id];if(v.o!==null)g.players[v.o].res[h.res]+=v.c?2:1})});return{}}
  if(!g.rolled)return{err:'Önce zar at'};
  if(t=='end'){g.turn=(g.turn+1)%g.players.length;g.rolled=false;return{}}
  if(t=='trade'){if(!RES.includes(b.give)||!RES.includes(b.get)||b.give==b.get)return{err:'Geçersiz takas'};
    const ratio=portRatio(me,b.give);
    if(p.res[b.give]<ratio)return{err:`Bu takas için ${ratio} ${C[b.give][0]} kartı lazım`};
    p.res[b.give]-=ratio;p.res[b.get]++;L(`${p.name} ${ratio}:1 liman/banka takası yaptı`);return{}}
  if(t=='road'){const e=g.E[b.id];if(!e||e.o!==null)return{err:'Buraya olmaz'};if(!roadOk(e,me))return{err:'Yol ağına bağlı değil'};
    if(!can(p,COST.road))return{err:'Kaynak yetersiz'};pay(p,COST.road);e.o=me;updateLongest()}
  else if(t=='settle'){const v=g.V[b.id];if(!v||!free(b.id))return{err:'Buraya olmaz'};if(!linked(b.id,me))return{err:'Yoluna bağlı olmalı'};
    if(!can(p,COST.settle))return{err:'Kaynak yetersiz'};pay(p,COST.settle);v.o=me;updateLongest();L(p.name+' köy kurdu')}
  else if(t=='city'){const v=g.V[b.id];if(!v||v.o!==me||v.c)return{err:'Kendi köyünü seç'};
    if(!can(p,COST.city))return{err:'Kaynak yetersiz'};pay(p,COST.city);v.c=true;L(p.name+' şehir yaptı')}
  else return{err:'Bilinmeyen hamle'};
  if(vp(me)>=10){g.phase='over';g.win=me}return{}}
function hints(i){
  const h={s:[],c:[],r:[]};if(g.turn!==i)return h;
  const V=Object.values(g.V),E=Object.values(g.E),p=g.players[i];
  if(g.phase=='setup'){if(g.st==='s')h.s=V.filter(v=>free(v.id)).map(v=>v.id);else if(g.st==='r'&&g.last)h.r=E.filter(e=>e.o===null&&(e.a===g.last||e.b===g.last)).map(e=>e.id)}
  else if(g.phase=='play'&&g.rolled&&!g.mustRob){
    h.r=E.filter(e=>e.o===null&&roadOk(e,i)).map(e=>e.id);
    h.s=V.filter(v=>free(v.id)&&linked(v.id,i)).map(v=>v.id);
    h.ar=can(p,COST.road)?h.r.slice():[];
    h.as=can(p,COST.settle)?h.s.slice():[];
    if(can(p,COST.city))h.c=V.filter(v=>v.o===i&&!v.c).map(v=>v.id)}
  return h}
function view(pid){return{me:pid,phase:g.phase,turn:g.turn,rolled:g.rolled,d:g.d,rob:g.rob,mustRob:g.mustRob,st:g.st,si:g.si,np:g.players.length,win:g.win,log:g.log,h:hints(pid),
  hexes:g.hexes.map(h=>({x:h.x,y:h.y,res:h.res,num:h.num})),V:Object.values(g.V),
  E:Object.values(g.E).map(e=>({id:e.id,o:e.o,a:e.a,b:e.b,x1:g.V[e.a].x,y1:g.V[e.a].y,x2:g.V[e.b].x,y2:g.V[e.b].y})),
  ports:(g.ports||[]).map(p=>({...p})),
  players:g.players.map((p,i)=>({name:p.name,col:p.col,hasDice:!!p.hasDice,vp:vp(i),road:roadLength(i),longest:g.longest===i,n:RES.reduce((n,r)=>n+p.res[r],0),res:i===pid?p.res:undefined}))}}

/* ---------- AĞ (PeerJS, tarayıcıdan tarayıcıya) ---------- */
function bc(){s=view(0);render();conns.forEach(c=>c.open&&c.send(view(c.pid)))}
function send(o){if(host){const r=act({...o,pid:0});if(r.err)toast(r.err);bc()}else if(conn)conn.send(o)}
function startHost(){
  const name=$('nm').value.trim()||'Oyuncu',code=Math.random().toString(36).slice(2,8).toUpperCase();
  if(typeof Peer!=='function'){toast('Çevrim içi bağlantı kütüphanesi yüklenemedi. Sayfayı yenile.');return}
  // PeerJS kimliği yalnızca harf/rakam içersin; oda kodu ayrı gösterilir.
  peer=new Peer('kadife'+code,{debug:1});
  peer.on('open',()=>{host=true;reset();act({t:'join',name,hasDice:$('hasDice').checked});$('lobby').hidden=true;
    const url=location.origin+location.pathname+'?oda='+code;
    $('room').innerHTML=`Oda kodu: <b style="font:800 20px Cinzel;color:#f2c94c">${code}</b> <button onclick="navigator.clipboard.writeText('${url}');toast('Bağlantı kopyalandı')">🔗 Davet linki</button>`;bc()});
  peer.on('error',e=>{
    const msg=e&&e.type?e.type:'bilinmeyen hata';
    toast(msg==='unavailable-id'?'Oda kodu çakıştı, tekrar dene.':'Oda kurulamadı: '+msg);
  });
  peer.on('disconnected',()=>toast('Sunucu bağlantısı kesildi. Sayfayı yenileyip tekrar dene.'));
  peer.on('connection',c=>{conns.push(c);
    c.on('data',d=>{
      if(d.t=='join'){const sp=g.players[d.sp];if(sp&&sp.name==d.name)c.pid=d.sp;else{const r=act(d);if(r.err)c.send({err:r.err});else c.pid=r.pid}}
      else{d.pid=c.pid;const r=act(d);if(r.err)c.send({err:r.err})}bc()});
    c.on('close',()=>{conns=conns.filter(x=>x!==c)})})}
function joinRoom(){
  const name=$('nm').value.trim()||'Oyuncu',code=$('cd').value.trim().toUpperCase();if(!code)return toast('Oda kodunu yaz');
  peer=new Peer();peer.on('error',e=>toast(e.type=='peer-unavailable'?'Oda bulunamadı':'Hata: '+e.type));
  peer.on('open',()=>{conn=peer.connect('kadife'+code,{reliable:true});
    conn.on('open',()=>{$('lobby').hidden=true;$('room').textContent='Oda: '+code;conn.send({t:'join',name,hasDice:$('hasDice').checked,sp:sessionStorage.pid!=null?+sessionStorage.pid:null})});
    conn.on('data',d=>{if(d.err)toast(d.err);else{s=d;if(d.me!=null)sessionStorage.pid=d.me;render()}});
    conn.on('error',e=>toast('Odaya bağlanılamadı: '+(e&&e.type?e.type:'bağlantı hatası')));
    conn.on('close',()=>toast('Bağlantı koptu'))})}

/* ---------- ARAYÜZ ---------- */
const cm=()=>s.phase=='setup'?(s.st==='s'?'s':'r'):mode;
function shownPortRatio(player,give){
  let ratio=4;
  const vertices=new Map((s.V||[]).map(v=>[v.id,v]));
  for(const port of (s.ports||[])){
    const a=vertices.get(port.a),b=vertices.get(port.b);
    if(!a||!b||(a.o!==player&&b.o!==player))continue;
    if(port.type===give)ratio=Math.min(ratio,2);
    else if(port.type==='any')ratio=Math.min(ratio,3);
  }
  return ratio;
}
// TAHTA ETKİLEŞİMİ — SVG hedef etiketlerine güvenmez.
// Fare/dokunma koordinatını SVG koordinatına çevirir, en yakın GEÇERLİ
// köşe/kenarı oyun grafiğinden bulur. Böylece çizim katmanları tıklamayı yutamaz.
function svgPointFromEvent(ev){
  const svg=$('b');
  if(svg.createSVGPoint && svg.getScreenCTM()){
    const p=svg.createSVGPoint(); p.x=ev.clientX; p.y=ev.clientY;
    return p.matrixTransform(svg.getScreenCTM().inverse());
  }
  const r=svg.getBoundingClientRect();
  return {x:-4.9+(ev.clientX-r.left)/r.width*9.8,
          y:-4.5+(ev.clientY-r.top)/r.height*9};
}
function pointSegDistance(p,e){
  const dx=e.x2-e.x1,dy=e.y2-e.y1,den=dx*dx+dy*dy||1;
  const t=Math.max(0,Math.min(1,((p.x-e.x1)*dx+(p.y-e.y1)*dy)/den));
  return Math.hypot(p.x-(e.x1+t*dx),p.y-(e.y1+t*dy));
}
function nearest(list,dist,max){
  let best=null,bd=max;
  for(const item of list){const d=dist(item);if(d<bd){bd=d;best=item;}}
  return best;
}
function handleBoardPointer(ev){
  if(!s || s.phase==='lobby' || s.phase==='over') return;
  if(ev.button!==undefined && ev.button!==0) return;
  const p=svgPointFromEvent(ev);
  // Kurulum: sadece mevcut adımın geçerli hamlesi kabul edilir.
  if(s.phase==='setup'){
    if(s.turn!==s.me) return;
    if(s.st==='s'){
      const v=nearest(s.V.filter(v=>s.h.s.includes(v.id)),v=>Math.hypot(p.x-v.x,p.y-v.y),.48);
      if(v){ev.preventDefault();send({t:'settle',id:v.id});}
      else toast('Altın halkalı köşe noktasına biraz daha yakından tıkla.');
      return;
    }
    if(s.st==='r'){
      const e=nearest(s.E.filter(e=>s.h.r.includes(e.id)),e=>pointSegDistance(p,e),.72);
      if(e){ev.preventDefault();send({t:'road',id:e.id});}
      else toast('Parlayan yol çizgisinin üzerine veya yakınına tıkla.');
      return;
    }
  }
  if(s.mustRob){
    const h=nearest(s.hexes.map((h,i)=>({...h,id:i})),h=>Math.hypot(p.x-h.x,p.y-h.y),.88);
    if(h && h.id!==s.rob){ev.preventDefault();send({t:'robber',h:h.id});}
    return;
  }
  if(s.phase!=='play' || s.turn!==s.me || !s.rolled) return;
  if(mode==='c'){
    const v=nearest(s.V.filter(v=>s.h.c.includes(v.id)),v=>Math.hypot(p.x-v.x,p.y-v.y),.48);
    if(v){ev.preventDefault();send({t:'city',id:v.id});}
    else toast('Parlayan şehir köşelerinden birine tıkla.');
    return;
  }
  // Yol ve köy aynı anda kurulabilir: tıklanan noktaya en yakın
  // geçerli hedef seçilir; böylece iki önergeyi de gizlemek gerekmez.
  // Tıklama hedefleri kaynak miktarından bağımsızdır. Böylece pasif köy/yol
  // işaretleri de kendi türünü korur; kaynak kontrolünü oyun motoru yapar.
  const road=nearest(s.E.filter(e=>(s.h.r||[]).includes(e.id)),e=>pointSegDistance(p,e),.72);
  const settle=nearest(s.V.filter(v=>(s.h.s||[]).includes(v.id)),v=>Math.hypot(p.x-v.x,p.y-v.y),.48);
  const rd=road?pointSegDistance(p,road)/.72:Infinity;
  const sd=settle?Math.hypot(p.x-settle.x,p.y-settle.y)/.48:Infinity;
  if(settle&&sd<=rd){ev.preventDefault();send({t:'settle',id:settle.id});}
  else if(road){ev.preventDefault();send({t:'road',id:road.id});}
  else toast('Köy için halkalı köşeye, yol için çizgiye tıkla.');
}
$('b').addEventListener('pointerup',handleBoardPointer,{passive:false});
$('b').addEventListener('click',ev=>{ev.preventDefault();},{passive:false});
const pts=(x,y,k=1)=>[0,1,2,3,4,5].map(i=>{const a=Math.PI/3*i-Math.PI/6;return(x+k*Math.cos(a)).toFixed(3)+','+(y+k*Math.sin(a)).toFixed(3)}).join(' ');
const SP=[[-.5,.45],[.5,.45],[-.5,-.45],[.5,-.45],[0,.7],[0,-.7]];
function render(){
  if(!s)return;guide();const me=s.me,P=s.players,lobby=s.phase=='lobby',my=!lobby&&s.turn==me,play=my&&s.phase=='play',cur=P[s.turn],col=o=>P[o].col,m=cm();
  $('st').textContent=lobby?`Lobi: ${P.length}/4 — arkadaşların bağlansın`:s.phase=='over'?`🏆 ${P[s.win].name} kazandı!`:s.phase=='setup'?`${cur.name}: ${s.st==='s'?'ÖNCE KÖYÜNÜ KUR':'ŞİMDİ KÖYÜNE BAĞLI BİR YOL KOY'}`:`${cur.name} oynuyor${s.mustRob?' · haydutu taşı!':''}`;
  $('win').hidden=s.phase!='over';if(s.win!=null)$('wt').textContent='🏆 '+P[s.win].name+' kazandı!';
  v2RenderPlayers(P,s,lobby,me);
  const r=P[me]&&P[me].res;const total=r?RES.reduce((n,k)=>n+(r[k]||0),0):0;
  $('resourceTotal').textContent=total+' kaynak kartı';
  $('resourceCards').innerHTML=r?RES.flatMap(k=>rep(Math.max(0,Math.min(30,r[k]||0)),k)).map((k,i)=>`<div class="resource-card" style="--fan:${i}" title="${C[k][0]}"><span class="card-type">KADİFE</span><img src="${RIMG[k]}" alt="${C[k][0]}"><span class="card-name">${C[k][0]}</span></div>`).join(''):'<div class="empty-hand">Kaynak kartların burada görünecek.</div>';
  const dk=s.d.join(),faces=['','⚀','⚁','⚂','⚃','⚄','⚅'];
  $('dice').innerHTML=s.d[0]?`<span class="die-face">${faces[s.d[0]]}</span><span class="die-face">${faces[s.d[1]]}</span>`:'<small>🎲 Zar sonucu burada görünecek</small>';
  $('dice').className='dice'+(dk!=lastDice?' rolling':'');lastDice=dk;
  const manual=!!(P[me]&&P[me].hasDice);
  $('start').hidden=!(lobby&&me==0&&P.length>1);$('roll').hidden=!(play&&!s.rolled&&!s.mustRob)||manual;
  $('manualRoll').hidden=!(play&&!s.rolled&&!s.mustRob&&manual);$('tools').hidden=!(play&&s.rolled&&!s.mustRob);
  $('mr').className=mode!=='c'?'on':'';
  $('mr').disabled=!((s.h.ar||[]).length||(s.h.as||[]).length);
  $('mc').className=mode==='c'?'on':'';
  $('mc').disabled=!s.h.c.length;
  $('tradeRate').textContent='Seçili kaynak: '+shownPortRatio(me,$('g1').value||'wood')+':1 (liman avantajı otomatik uygulanır)';
  $('log').innerHTML=s.log.map(x=>`<div>${x}</div>`).join('');
  $('b').innerHTML=DEFS+'<rect x=-9 y=-9 width=18 height=18 fill="url(#oc)"/><rect x=-9 y=-9 width=18 height=18 fill="url(#wv)"/>'+
  s.hexes.map(h=>`<polygon points="${pts(h.x,h.y,1.13)}" fill="#e6d3a0" filter="url(#sh)"/>`).join('')+
  s.hexes.map((h,i)=>`<g class="${s.mustRob&&my&&i!=s.rob?'glow k':''}" data-hit="hex" data-id="${i}"><polygon points="${pts(h.x,h.y,.97)}" fill="url(#g${h.res})" stroke="#4a2b17" stroke-width=".055" filter="url(#sh)"/><polygon points="${pts(h.x,h.y,.91)}" fill="none" stroke="#fff7" stroke-width=".025"/>`+
    SP.map(([x,y])=>`<use href="#i${h.res}" x="${h.x+x}" y="${h.y+y}"/>`).join('')+
    (h.num?`<circle cx="${h.x}" cy="${h.y}" r=".31" fill="#f3e6c4" stroke="#7a5b2b" stroke-width=".03" filter="url(#sh)"/><text x="${h.x}" y="${h.y+.06}" text-anchor="middle" font-family="Cinzel,serif" font-weight="800" font-size=".3" fill="${h.num==6||h.num==8?'#b3261e':'#2b2b2b'}">${h.num}</text><text x="${h.x}" y="${h.y+.24}" text-anchor="middle" font-size=".2" fill="${h.num==6||h.num==8?'#b3261e':'#555'}">${'•'.repeat(6-Math.abs(7-h.num))}</text>`:'')+'</g>').join('')+
  `<g transform="translate(${s.hexes[s.rob].x+.38},${s.hexes[s.rob].y-.2})" filter="url(#sh)"><path d="M-.12.2Q-.1-.05 0-.05Q.1-.05 .12.2Z" fill="#1a1a1a" stroke="#fff4" stroke-width=".02"/><circle cy="-.13" r=".08" fill="#1a1a1a"/></g>`+
     (s.ports||[]).map(p=>{const labels={any:'⚓ 3:1',wood:'🪵 2:1',brick:'🧱 2:1',sheep:'🐑 2:1',wheat:'🌾 2:1',ore:'⛰️ 2:1'};return `<g transform="translate(${p.x},${p.y})" filter="url(#sh)" pointer-events="none"><rect x="-.34" y="-.14" width=".68" height=".28" rx=".08" fill="#f5e5c2" stroke="#684522" stroke-width=".035"/><text x="0" y=".055" text-anchor="middle" font-size=".145" font-weight="800" fill="#49301c">${labels[p.type]}</text></g>`}).join('')+
     s.E.map(e=>{const dx=e.x2-e.x1,dy=e.y2-e.y1,a=[e.x1+dx*.14,e.y1+dy*.14],b=[e.x1+dx*.86,e.y1+dy*.86],ln=(w,c,x='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${c}" stroke-width="${w}" stroke-linecap="round" ${x}/>`;
     const active=e.o===null&&s.h&&((s.phase==='play'?(s.h.ar||[]):(s.h.r||[])).includes(e.id));
     const passive=e.o===null&&s.phase==='play'&&s.h.r&&s.h.r.includes(e.id)&&!(s.h.ar||[]).includes(e.id);
     return e.o!=null?ln(.22,'#382312')+ln(.15,col(e.o)):(active?ln(.23,'#ffd76a','class=glow')+ln(.105,'#fff4cf'):(passive?ln(.075,'#b8c5ce','stroke-dasharray=.07 .09') :''))}).join('')+
   edgeHits()+
   s.V.map(v=>{const c=v.o!=null?col(v.o):'';let d='';
     if(v.o!=null){
       d=v.c?`<g transform="translate(${v.x},${v.y})" filter="url(#sh)"><path d="M-.29,.19L-.25,.25H.25L.29,.19Z" fill="#79502b" stroke="#3c2514" stroke-width=".025"/><path d="M-.25,.17V-.07H-.07V-.2H.07V-.07H.25V.17Z" fill="#dfc18f" stroke="#684522" stroke-width=".035"/><path d="M-.29,-.055L-.12,-.25H.12L.29,-.055Z" fill="${c}" stroke="#542d1b" stroke-width=".04"/><path d="M-.055,.17V.015H.055V.17Z" fill="#69401f"/><rect x="-.205" y="-.035" width=".065" height=".075" rx=".012" fill="#8fc4d1" stroke="#69401f" stroke-width=".018"/><rect x=".14" y="-.035" width=".065" height=".075" rx=".012" fill="#8fc4d1" stroke="#69401f" stroke-width=".018"/></g>`:
       `<g transform="translate(${v.x},${v.y})" filter="url(#sh)"><path d="M-.24,.17L-.21,.23H.21L.24,.17Z" fill="#79502b" stroke="#3c2514" stroke-width=".025"/><path d="M-.2,.16V-.035L0,-.2L.2,-.035V.16Z" fill="#e4c99b" stroke="#684522" stroke-width=".035"/><path d="M-.245,-.025L0,-.29L.245,-.025Z" fill="${c}" stroke="#542d1b" stroke-width=".04"/><path d="M-.055,.16V.025H.055V.16Z" fill="#69401f"/><rect x="-.15" y=".015" width=".06" height=".065" rx=".01" fill="#8fc4d1" stroke="#69401f" stroke-width=".018"/><rect x=".09" y=".015" width=".06" height=".065" rx=".01" fill="#8fc4d1" stroke="#69401f" stroke-width=".018"/></g>`;
     }
     const active=((s.phase==='play'?(s.h.as||[]):(s.h.s||[])).includes(v.id))||(s.h.c&&s.h.c.includes(v.id));
     const passive=s.phase==='play'&&s.h.s&&s.h.s.includes(v.id)&&!(s.h.as||[]).includes(v.id);
     const hl=active?`<circle class="glow" cx="${v.x}" cy="${v.y}" r=".36" fill="#ffd76a" fill-opacity=".24" stroke="#fff0a8" stroke-width=".09"/><circle cx="${v.x}" cy="${v.y}" r=".25" fill="none" stroke="#fff9df" stroke-width=".04" stroke-dasharray=".07 .045"/>`:passive?`<circle cx="${v.x}" cy="${v.y}" r=".29" fill="#d7e0e8" fill-opacity=".13" stroke="#d7e0e8" stroke-width=".055" stroke-dasharray=".06 .055"/>`:'';
     return`<g class=k data-hit="vertex" data-id="${v.id}" style="pointer-events:all;cursor:pointer">${hl}${d}<circle cx="${v.x}" cy="${v.y}" r=".31" fill="transparent" pointer-events="all"/></g>`}).join('')}
function edgeHits(){return s.E.filter(e=>e.o===null&&s.h&&(s.h.ar||s.h.r||[]).includes(e.id)).map(e=>{const dx=e.x2-e.x1,dy=e.y2-e.y1;return`<line class=k x1="${e.x1+dx*.22}" y1="${e.y1+dy*.22}" x2="${e.x1+dx*.78}" y2="${e.y1+dy*.78}" stroke="transparent" stroke-width=".72" pointer-events="stroke" data-hit="edge" data-id="${e.id}"/>`}).join('')}
function guide(){
  const me=s.me,P=s.players,cur=P[s.turn],my=s.turn==me,h=s.h,box=$('guide');let t;
  if(s.phase=='lobby')t=me==0?'👑 Odayı sen kurdun. Arkadaşların <b>oda kodunu</b> girince <b>▶ Oyunu başlat</b>a bas (en az 2 kişi).':'Oda kurucusunun oyunu başlatmasını bekle.';
  else if(s.phase=='over')t='🎉 Oyun bitti! Yeni oyun için butona bas.';
  else if(me==null||!P[me])t='İzleyicisin.';
  else if(!my)t=`⏳ Sıra <b>${cur.name}</b> oyuncusunda. Beklerken: zarda senin arazine denk gelen sayı çıkarsa kartların otomatik artar.`;
  else if(s.phase=='setup'){const r2=s.si>=s.np;
    t=s.st=='s'?`<b>Adım 1/2 — Köyünü kur</b><br>Haritada <b>parlayan altın halkalardan</b> birine tıkla.${r2?'<br>🎁 Bu 2. köyün: çevresindeki her araziden 1 kaynak kazanırsın.':''}<br>💡 6, 8, 5, 9 gibi sık çıkan sayılara ve farklı kaynaklara değen köşe iyidir.`
      :`<b>Adım 2/2 — Yol koy</b><br>Az önce kurduğun köyün yanındaki <b>parlayan çizgilerden</b> birine veya çizginin hemen yakınına tıkla.`}
  else if(s.mustRob)t='🦹 <b>7 geldi!</b> Haydutu taşı: <b>parlayan bir araziye</b> tıkla. O arazi üretmez; yanında köyü olan birinden kart çalarsın.';
  else if(!s.rolled)t='<b>1. Önce 🎲 Zar at</b> butonuna bas. Çıkan sayıdaki araziler kaynak verir.';
  else{
    if(mode==='c'&&!h.c.length)mode='auto';
    const L=[];
    if(h.c.length)L.push('🏙️ <b>Şehir</b>: <i>Şehir</i> butonu → parlayan köyüne tıkla (+1 puan)');
    if((h.as||[]).length)L.push('🏠 <b>Köy</b>: altın halkalı köşeye tıkla (+1 puan)');
    else if(h.s.length)L.push('🏠 <b>Köy yerleri</b>: soluk halkalar görünür; kaynakların yetmiyor.');
    if((h.ar||[]).length)L.push('🛣️ <b>Yol</b>: altın çizgiye tıkla');
    else if(h.r.length)L.push('🛣️ <b>Yol yerleri</b>: soluk çizgiler görünür; kaynakların yetmiyor.');
    t='<b>2. Kur ya da takas yap</b><br>'+(L.length?L.join('<br>'):'Şu an kaynağın bir şey kurmaya yetmiyor. Aynı türden 4 kartı bankada 1 karta çevirebilirsin (Takas).')+'<br><b>3. İşin bitince ➜ Turu bitir</b>'}
  box.innerHTML=t+'<br><button onclick="$(\'rules\').hidden=false">📖 Kurallar</button>';
}
